-- Identify the products that generated the highest sales revenue
-- by grouping sales transactions by product code and description
-- and calculating the total revenue generated by each product
Select  Top 10  
	StockCode,
	Description,
	SUM(Quantity * Price) AS Total_Sales
From online_retail_cleaned
WHERE Transaction_Type = 'Sales'
Group By 
	StockCode,
	Description
Order By Total_Sales DESC;



-- Identify non-product transaction codes
-- to separate actual products from postage, manual entries, and other service transactions
SELECT DISTINCT
    StockCode,
    Description
FROM online_retail_cleaned
WHERE Transaction_Type = 'Sales'
ORDER BY StockCode;


-- Check the descriptions of the highest-revenue items
-- to identify transaction codes that are not actual products
SELECT
    StockCode,
    Description,
    SUM(Quantity * Price) AS Total_Sales
FROM online_retail_cleaned
WHERE Transaction_Type = 'Sales'
GROUP BY
    StockCode,
    Description
ORDER BY Total_Sales DESC;



-- Calculate product sales after excluding non-product transaction codes
-- to identify the highest-revenue actual products
Select Top 10 
	StockCode,
	Description,
	SUM(Quantity * Price) AS Total_Sale
From online_retail_cleaned
WHERE Transaction_Type = 'Sales'
	AND StockCode NOT IN ('M', 'DOT', 'POST')
Group BY
	StockCode,
	Description
Order By 
	Total_Sale DESC;



-- Compare products based on the quantity sold
-- to determine which products have the highest sales volume
Select Top 10 
	StockCode,
	Description,
	SUM(Quantity) AS Total_Quantity
From online_retail_cleaned
WHERE Transaction_Type = 'Sales'
	AND StockCode NOT IN ('M', 'DOT', 'POST')
Group BY
	StockCode,
	Description
Order By 
	Total_Quantity DESC;



-- Compare the average selling price of products
-- to understand whether high-revenue products are driven by higher prices
Select TOP 10
	StockCode,
	Description,
	SUM(Quantity) AS Total_Qauntity,
	SUM(Quantity * Price) AS Total_Sales,
	AVG(Price) AS Average_Unit_Price
From online_retail_cleaned
WHERE Transaction_Type = 'Sales'
	AND StockCode NOT IN ('M', 'DOT', 'POST')
Group By
	StockCode,
	Description
Order By
	Total_Sales DESC;


-- Identify high-volume products with relatively low total sales
-- to find products with strong demand but lower revenue contribution
WITH ProductMetrics AS (
    SELECT 
        StockCode,
        Description,
        SUM(Quantity) AS Total_Quantity,
        SUM(Quantity * Price) AS Total_Sales,
        AVG(Price) AS Average_Unit_Price
    FROM online_retail_cleaned
    WHERE Transaction_Type = 'Sales'
      AND StockCode NOT IN ('M', 'DOT', 'POST')
    GROUP BY 
        StockCode,
        Description
)
SELECT 
    StockCode,
    Description,
    Total_Quantity,
    Total_Sales,
    Average_Unit_Price
FROM ProductMetrics
WHERE Total_Quantity > (SELECT AVG(Total_Quantity) FROM ProductMetrics)
  AND Total_Sales < (SELECT AVG(Total_Sales) FROM ProductMetrics)
ORDER BY 
    Total_Quantity DESC;